import{_ as a,o as r,c as o,a3 as e}from"./chunks/framework.Bh_aNVBG.js";const i="/images/project-admin/image.png",l="/images/project-admin/image%201.png",d="/images/project-admin/image%202.png",n="/images/project-admin/image%203.png",u=JSON.parse('{"title":"2. CMS 시작하기","description":"","frontmatter":{},"headers":[],"relativePath":"project-admin/chapter-2.md","filePath":"project-admin/chapter-2.md"}'),s={name:"project-admin/chapter-2.md"};function h(p,t,c,m,g,_){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="_2-cms-시작하기" tabindex="-1">2. CMS 시작하기 <a class="header-anchor" href="#_2-cms-시작하기" aria-label="Permalink to &quot;2. CMS 시작하기&quot;">​</a></h1><h2 id="_2-1-cms-접속-및-로그인" tabindex="-1">2.1. CMS 접속 및 로그인 <a class="header-anchor" href="#_2-1-cms-접속-및-로그인" aria-label="Permalink to &quot;2.1. CMS 접속 및 로그인&quot;">​</a></h2><p>인포디오 CMS는 웹 브라우저를 통해 접속할 수 있는 관리자 페이지입니다.</p><p>CMS에 로그인하면 프로젝트를 조회하고, 권한에 따라 행사 안내 페이지의 콘텐츠와 서비스 설정을 관리할 수 있습니다.</p><h3 id="_1-cms-접속" tabindex="-1">① CMS 접속 <a class="header-anchor" href="#_1-cms-접속" aria-label="Permalink to &quot;① CMS 접속&quot;">​</a></h3><ol><li>Chrome, Edge 등 웹 브라우저를 실행합니다.</li><li><a href="https://infodio.kr/cms/" target="_blank" rel="noreferrer">https://infodio.kr/cms/</a> 를 주소창에 입력합니다.</li><li>인포디오 CMS 로그인 화면이 표시됩니다.</li></ol><p><img src="'+i+'" alt="image.png"></p><h3 id="_2-로그인" tabindex="-1">② 로그인 <a class="header-anchor" href="#_2-로그인" aria-label="Permalink to &quot;② 로그인&quot;">​</a></h3><ol><li><strong>Email</strong> 입력란에 발급받은 관리자 이메일을 입력합니다.</li><li><strong>Password</strong> 입력란에 비밀번호를 입력합니다.</li><li><strong>로그인</strong> 버튼을 클릭합니다.</li><li>로그인이 완료되면 관리자 페이지로 이동합니다.</li></ol><blockquote><p><strong>참고</strong></p><ul><li>CMS 계정은 관리자를 통해 발급됩니다.</li><li>로그인 정보가 올바르지 않은 경우 오류 메시지가 표시됩니다.</li><li>계정 관련 문의는 고객지원(<a href="mailto:support@infodio.kr" target="_blank" rel="noreferrer">support@infodio.kr</a>)으로 연락해 주세요.</li></ul></blockquote><hr><h2 id="_2-2-비밀번호-재설정" tabindex="-1">2.2. 비밀번호 재설정 <a class="header-anchor" href="#_2-2-비밀번호-재설정" aria-label="Permalink to &quot;2.2. 비밀번호 재설정&quot;">​</a></h2><p>비밀번호를 잊어버린 경우, 로그인 화면에서 이메일 인증을 통해 비밀번호를 재설정할 수 있습니다.</p><h3 id="_1-비밀번호-재설정-요청" tabindex="-1">① 비밀번호 재설정 요청 <a class="header-anchor" href="#_1-비밀번호-재설정-요청" aria-label="Permalink to &quot;① 비밀번호 재설정 요청&quot;">​</a></h3><ol><li>CMS 로그인 화면으로 이동합니다.</li><li><strong>메일로 비밀번호 재설정 링크 전송</strong> 버튼을 클릭합니다.</li><li>비밀번호 재설정 창이 표시되면 계정에 등록된 이메일 주소를 입력합니다.</li><li><strong>전송</strong> 버튼을 클릭합니다.</li><li>입력한 이메일로 발송된 비밀번호 재설정 안내 메일을 확인합니다.</li></ol><p><img src="'+l+'" alt="image.png"></p><h3 id="_2-새-비밀번호-설정" tabindex="-1">② 새 비밀번호 설정 <a class="header-anchor" href="#_2-새-비밀번호-설정" aria-label="Permalink to &quot;② 새 비밀번호 설정&quot;">​</a></h3><ol><li>수신한 이메일에서 비밀번호 재설정 링크를 클릭합니다.</li><li>새로운 비밀번호를 입력합니다.</li><li>비밀번호 확인란에 동일한 비밀번호를 다시 입력합니다.</li><li><strong>확인</strong> 버튼을 클릭하여 변경을 완료합니다.</li><li>로그인 화면으로 돌아가 변경한 비밀번호로 로그인합니다.</li></ol><p>비밀번호는 다음 조건을 충족해야 합니다.</p><ul><li>6~20자</li><li>영문 대문자 및 소문자 포함</li><li>숫자 포함</li><li>특수문자 포함</li></ul><blockquote><p><strong>주의사항</strong></p><p>비밀번호 재설정 이메일이 도착하지 않는 경우 스팸 메일함을 확인해 주세요. 등록되지 않은 이메일이거나 문제가 지속되는 경우 관리자에게 문의해 주세요.</p></blockquote><hr><h2 id="_2-3-프로젝트-관리-화면" tabindex="-1">2.3. 프로젝트 관리 화면 <a class="header-anchor" href="#_2-3-프로젝트-관리-화면" aria-label="Permalink to &quot;2.3. 프로젝트 관리 화면&quot;">​</a></h2><p>CMS에 로그인하면 등록된 프로젝트 목록을 확인할 수 있는 <strong>프로젝트 관리 화면</strong>이 표시됩니다.</p><p>프로젝트 관리 화면에서는 프로젝트의 기본 정보와 운영 상태를 확인하고 계정에 할당된 프로젝트를 선택할 수 있습니다.</p><h3 id="_1-화면-구성" tabindex="-1">① 화면 구성 <a class="header-anchor" href="#_1-화면-구성" aria-label="Permalink to &quot;① 화면 구성&quot;">​</a></h3><p><img src="'+d+'" alt="image.png"></p><table tabindex="0"><thead><tr><th>번호</th><th>영역</th><th>설명</th></tr></thead><tbody><tr><td>①</td><td>연도 선택</td><td>선택한 연도의 프로젝트 목록을 조회합니다.</td></tr><tr><td>②</td><td>프로젝트 목록</td><td>등록된 프로젝트의 기본 정보와 운영 상태를 확인합니다.</td></tr><tr><td>③</td><td>관리</td><td>해당 프로젝트의 관리 화면으로 이동합니다.</td></tr><tr><td>④</td><td>페이지 이동</td><td>목록의 페이지를 이동하거나 페이지당 표시 개수를 변경합니다.</td></tr></tbody></table><h3 id="_2-프로젝트-목록-항목-안내" tabindex="-1">② 프로젝트 목록 항목 안내 <a class="header-anchor" href="#_2-프로젝트-목록-항목-안내" aria-label="Permalink to &quot;② 프로젝트 목록 항목 안내&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>프로젝트 명</td><td>등록된 축제 또는 행사 프로젝트의 이름</td></tr><tr><td>기간</td><td>프로젝트에 설정된 행사 시작일 및 종료일</td></tr><tr><td>URL</td><td>방문객용 안내 페이지 접속 주소</td></tr><tr><td>주최/주관</td><td>프로젝트에 등록된 주최 및 주관 정보</td></tr><tr><td>담당자</td><td>프로젝트 담당자 정보</td></tr><tr><td>상태</td><td>프로젝트의 현재 운영 상태</td></tr><tr><td>관리</td><td>해당 프로젝트의 관리 화면으로 이동하는 버튼</td></tr></tbody></table><h3 id="_3-프로젝트-목록-조회" tabindex="-1">③ 프로젝트 목록 조회 <a class="header-anchor" href="#_3-프로젝트-목록-조회" aria-label="Permalink to &quot;③ 프로젝트 목록 조회&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 조회하려는 연도를 선택합니다.</li><li>해당 연도에 등록된 프로젝트 목록을 확인합니다.</li><li>프로젝트명, 행사 기간 및 운영 상태를 확인하여 관리할 프로젝트를 찾습니다.</li></ol><blockquote><p><strong>참고</strong></p><p>조회하려는 프로젝트가 목록에 표시되지 않는 경우 선택한 연도를 확인해 주세요.</p><p>방문객용 안내 페이지는 프로젝트가 활성화된 상태에서 이용할 수 있습니다. 프로젝트 상태 및 공개 설정에 관한 자세한 내용은 <strong>9. 안내 페이지 공개 및 운영</strong>에서 안내합니다.</p></blockquote><hr><h2 id="_2-4-프로젝트별-관리-화면" tabindex="-1">2.4. 프로젝트별 관리 화면 <a class="header-anchor" href="#_2-4-프로젝트별-관리-화면" aria-label="Permalink to &quot;2.4. 프로젝트별 관리 화면&quot;">​</a></h2><p>프로젝트별 관리 화면에서는 선택한 프로젝트의 기본 정보, 콘텐츠 및 서비스 설정을 관리할 수 있습니다.</p><h3 id="_1-프로젝트별-관리-화면-이동" tabindex="-1">① 프로젝트별 관리 화면 이동 <a class="header-anchor" href="#_1-프로젝트별-관리-화면-이동" aria-label="Permalink to &quot;① 프로젝트별 관리 화면 이동&quot;">​</a></h3><ol><li><strong>프로젝트 관리</strong> 화면에서 관리할 프로젝트를 찾습니다.</li><li>해당 프로젝트의 <strong>관리</strong> 버튼을 클릭합니다.</li><li>새로운 브라우저 탭에서 프로젝트별 관리 화면이 열립니다.</li><li>관리하려는 기능에 해당하는 메뉴를 선택합니다.</li></ol><p><img src="'+n+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>프로젝트의 초기 설정이 완료되지 않은 경우 초기 설정 화면이 표시될 수 있습니다.</p><p>단계별 초기 설정 방법은 <strong>2.4. 신규 프로젝트 생성</strong>을 참고해 주세요.</p></blockquote><h3 id="_2-주요-관리-기능" tabindex="-1">② 주요 관리 기능 <a class="header-anchor" href="#_2-주요-관리-기능" aria-label="Permalink to &quot;② 주요 관리 기능&quot;">​</a></h3><p>프로젝트별 관리 화면에서 이용할 수 있는 주요 기능은 다음과 같습니다.</p><table tabindex="0"><thead><tr><th>관리 영역</th><th>주요 기능</th></tr></thead><tbody><tr><td>프로젝트 설정</td><td>프로젝트 기본 정보 및 서비스 설정</td></tr><tr><td>홈 화면</td><td>메인 배너, 하이라이트, 바로가기 및 푸터 관리</td></tr><tr><td>콘텐츠</td><td>상세 콘텐츠 및 공지사항 관리</td></tr><tr><td>투어맵</td><td>지도 설정, 마커, 구역 및 오버레이 관리</td></tr><tr><td>일정</td><td>행사 일정 및 카테고리 관리</td></tr><tr><td>스탬프 투어</td><td>스탬프 코스, 수집 지점 및 보상 관리</td></tr><tr><td>부가 서비스</td><td>AI 챗봇, 설문조사, 오디오·비디오 가이드 등 관리</td></tr><tr><td>대시보드 및 통계</td><td>방문객 현황 및 서비스 이용 통계 조회</td></tr></tbody></table><blockquote><p><strong>참고</strong></p><p>실제 표시되는 관리 메뉴는 프로젝트의 설정, 활성화된 서비스에 따라 다를 수 있습니다.</p><p>각 관리 기능의 세부 설정 및 이용 방법은 이후 각 장에서 안내합니다.</p></blockquote><hr>',45)])])}const q=a(s,[["render",h]]);export{u as __pageData,q as default};
